#!/usr/bin/env python3
"""Keep native dataset metadata synchronized with the Python public catalogue."""
import argparse
from dataclasses import asdict
import json
from pathlib import Path
from horus.remote_rendering.scene_catalog import ADVANCED_REMOTE_SCENES
from horus.remote_rendering.real_scene import ETH3D_REMOTE_SCENES, COW_LADY_VIEW_SPECS, ETH3D_COURTYARD_VIEW_SPECS, ETH3D_COURTYARD_SCANS

p = argparse.ArgumentParser()
p.add_argument("--check", action="store_true")
a = p.parse_args()
cache = Path.home() / ".cache/horus"
scenes = []
for scene in ADVANCED_REMOTE_SCENES.values():
    item = asdict(scene)
    item["cache_path"] = str(scene.cache_path.relative_to(cache))
    scenes.append(item)
data = dict(advanced=scenes, eth3d=ETH3D_REMOTE_SCENES,
            cow_views=[asdict(v) for v in COW_LADY_VIEW_SPECS],
            courtyard_views=[asdict(v) for v in ETH3D_COURTYARD_VIEW_SPECS],
            courtyard_scans=[dict(filename=n, alignment=m.tolist()) for n, m in ETH3D_COURTYARD_SCANS])
text = '// Generated by .github/scripts/generate_scene_catalog.py; do not edit.\nR"CATALOG(' + json.dumps(data, sort_keys=True, separators=(",", ":")) + ')CATALOG"\n'
path = Path(__file__).parents[2] / "rust/native/core/scene_catalog.inc"
if a.check:
    assert path.read_text() == text, "Native scene catalogue differs from Python; regenerate it"
else:
    path.write_text(text)
